CREATE TABLE IF NOT EXISTS message_analysis_records (id INTEGER PRIMARY KEY, input_sha256 VARCHAR(64) NOT NULL, source_type VARCHAR(30) NOT NULL DEFAULT 'TEXT', result_json TEXT NOT NULL, created_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_message_analysis_records_input_sha256 ON message_analysis_records(input_sha256);
CREATE TABLE IF NOT EXISTS message_indicator_results (id INTEGER PRIMARY KEY, message_analysis_id INTEGER, email_analysis_id INTEGER, indicator_type VARCHAR(30) NOT NULL, indicator VARCHAR(2048) NOT NULL, provider VARCHAR(120) NOT NULL, status VARCHAR(30) NOT NULL, verdict VARCHAR(30) NOT NULL, result_json TEXT NOT NULL, checked_at TIMESTAMP, FOREIGN KEY(message_analysis_id) REFERENCES message_analysis_records(id), FOREIGN KEY(email_analysis_id) REFERENCES email_analyses(id));
CREATE INDEX IF NOT EXISTS ix_message_indicator_results_message_analysis_id ON message_indicator_results(message_analysis_id);
CREATE INDEX IF NOT EXISTS ix_message_indicator_results_email_analysis_id ON message_indicator_results(email_analysis_id);
CREATE TABLE IF NOT EXISTS message_domain_spoofing_findings (id INTEGER PRIMARY KEY, message_analysis_id INTEGER, email_analysis_id INTEGER, observed_domain VARCHAR(255) NOT NULL, official_domain VARCHAR(255), brand VARCHAR(120), similarity FLOAT, edit_distance INTEGER, technique VARCHAR(120), confidence VARCHAR(30), verification_status VARCHAR(30), evidence_json TEXT NOT NULL, created_at TIMESTAMP, FOREIGN KEY(message_analysis_id) REFERENCES message_analysis_records(id), FOREIGN KEY(email_analysis_id) REFERENCES email_analyses(id));
CREATE INDEX IF NOT EXISTS ix_message_domain_spoofing_findings_message_analysis_id ON message_domain_spoofing_findings(message_analysis_id);
